  (:require [clojure-algorithms.runtime.python :refer :all] [clojure.string :as str]))

(declare padovan-sequence)

(defn padovan-sequence "Return the n-th term of the Padovan Sequence.\nThe Padovan sequence is the sequence of integers P(n) defined by the initial values\nP(0) = P(1) = P(2) = 1 and the recurrence relation P(n) = P(n-2) + P(n-3).\n\nhttps://en.wikipedia.org/wiki/Padovan_sequence\n\n:param n: The index of the term to return.\n:return: The n-th term of the Padovan Sequence.\n\n>>> padovan_sequence(0)\n1\n>>> padovan_sequence(1)\n1\n>>> padovan_sequence(2)\n1\n>>> padovan_sequence(3)\n2\n>>> padovan_sequence(4)\n2\n>>> padovan_sequence(5)\n3\n>>> padovan_sequence(10)\n12\n>>> padovan_sequence(-1)\nTraceback (most recent call last):\n    ...\nValueError: Input must be a non-negative integer."
  [n] (let [--v (atom nil) curr (atom nil) p-prev-1 (atom nil) p-prev-2 (atom nil) p-prev-3 (atom nil)] (try (when (py-truthy (let [__b1 (not (py-truthy (integer? n)))] (if (py-truthy __b1) __b1 (py-lt n 0)))) (throw (ex-info (py-str "Input must be a non-negative integer.") {:type :ValueError}))) (when (py-truthy (py-le n 2)) (throw (ex-info "__return__" {:__control__ true :__return__ true :value 1}))) (let [__d2 (vec [1 1 1])] (reset! p-prev-3 (nth __d2 0)) (reset! p-prev-2 (nth __d2 1)) (reset! p-prev-1 (nth __d2 2))) (doseq [__i3 (py-iter (range 3 (py-add n 1)))] (reset! --v __i3) (reset! curr (py-add @p-prev-2 @p-prev-3)) (let [__d4 (vec [@p-prev-2 @p-prev-1 @curr])] (reset! p-prev-3 (nth __d4 0)) (reset! p-prev-2 (nth __d4 1)) (reset! p-prev-1 (nth __d4 2)))) (throw (ex-info "__return__" {:__control__ true :__return__ true :value @p-prev-1})) (catch clojure.lang.ExceptionInfo __e (if (:__return__ (ex-data __e)) (:value (ex-data __e)) (throw __e))))))
